---@alias gcp.unstable.ces_v1beta.GuardrailContentFilterMatchTypeEnum "MATCH_TYPE_UNSPECIFIED"|"SIMPLE_STRING_MATCH"|"WORD_BOUNDARY_STRING_MATCH"|"REGEXP_MATCH"|"SENSITIVE_WORDS"

