---@alias gcp.unstable.ces_v1beta.GuardrailLlmPolicyPolicyScopeEnum "POLICY_SCOPE_UNSPECIFIED"|"USER_QUERY"|"AGENT_RESPONSE"|"USER_QUERY_AND_AGENT_RESPONSE"

